import React from "react";
import { useNavigate } from "react-router-dom";

const GRADIENTS = ["rt1","rt2","rt3","rt4","rt5","rt6"];

export default function RoomCard({ room, index = 0 }) {
  const navigate = useNavigate();
  const grad = GRADIENTS[index % GRADIENTS.length];
  const imageUrl = room.images?.[0] || `https://picsum.photos/seed/roomly-${room._id || index}/800/600`;

  const services = typeof room.services === "string"
    ? room.services.split(",").slice(0, 3).map(s => s.trim())
    : [];

  const svcIcon = (s) => {
    const l = s.toLowerCase();
    if (l.includes("wifi")) return "📶";
    if (l.includes("ac") || l.includes("air")) return "❄️";
    if (l.includes("park")) return "🅿️";
    if (l.includes("pool")) return "🌊";
    if (l.includes("gym")) return "🏋️";
    if (l.includes("kitchen")) return "🍳";
    if (l.includes("breakfast")) return "☕";
    if (l.includes("tv")) return "📺";
    return "✨";
  };

  const discountedPrice = room.discountRate > 0
    ? Math.round(room.pricePerNight * (1 - room.discountRate / 100))
    : null;

  return (
    <div
      className="card"
      onClick={() => navigate(`/rooms/${room._id}`)}
      style={{ cursor: "pointer" }}
    >
      {/* Thumbnail */}
      <div
        className={`${grad}`}
        style={{
          height: 180,
          position: "relative",
          backgroundImage: `linear-gradient(180deg, rgba(0,0,0,.08), rgba(0,0,0,.35)), url(${imageUrl})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        {room.discountRate > 0 && (
          <span style={{
            position: "absolute", top: 12, left: 12,
            background: "var(--coral)", color: "white",
            fontSize: 10, fontWeight: 700, padding: "3px 8px", borderRadius: 999,
          }}>−{room.discountRate}%</span>
        )}

        <span style={{
          position: "absolute", bottom: 12, left: 12,
          background: "rgba(255,255,255,.15)", backdropFilter: "blur(6px)",
          border: "1px solid rgba(255,255,255,.3)", color: "white",
          fontSize: 10, fontWeight: 700, padding: "3px 10px", borderRadius: 999, letterSpacing: ".6px",
        }}>{room.type?.toUpperCase()}</span>
      </div>

      {/* Body */}
      <div style={{ padding: "14px 16px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 4 }}>
          <div style={{ fontWeight: 600, fontSize: 15 }}>{room.title || room.description?.substring(0, 30) || room.type}</div>
          <div style={{ display: "flex", alignItems: "center", gap: 2 }}>
            <span className="star-gold">★</span>
            <span style={{ fontSize: 13, fontWeight: 600 }}>4.9</span>
          </div>
        </div>
        <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 6 }}>
          📍 {room.location} · {room.city}
        </div>
        <div style={{ display: "flex", gap: 10, fontSize: 12, color: "var(--muted)", marginBottom: 10 }}>
          <span>🛏 {room.beds_num} bed{room.beds_num > 1 ? "s" : ""}</span>
          <span>👥 {room.maxGuests}</span>
          {room.space && <span>📐 {room.space} m²</span>}
        </div>
        <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
          {services.map((s, i) => (
            <span key={i} style={{
              fontSize: 11, background: "var(--tag)", padding: "3px 8px", borderRadius: 999, color: "var(--muted)"
            }}>{svcIcon(s)}</span>
          ))}
        </div>
      </div>

      {/* Footer */}
      <div style={{
        display: "flex", justifyContent: "space-between", alignItems: "center",
        padding: "12px 16px", borderTop: "1px solid var(--border)",
      }}>
        <div>
          <span style={{ fontFamily: "'DM Serif Display',serif", fontSize: 20 }}>
            ${discountedPrice ?? room.pricePerNight}
          </span>
          <span style={{ fontSize: 12, color: "var(--muted)", fontWeight: 400 }}> / night</span>
          {discountedPrice && (
            <span style={{ fontSize: 11, color: "var(--coral)", textDecoration: "line-through", marginLeft: 6 }}>
              ${room.pricePerNight}
            </span>
          )}
        </div>
        <span
          style={{
            background: room.availableNow === false ? "var(--coral-lt)" : "var(--teal-lt)",
            color: room.availableNow === false ? "var(--coral)" : "var(--teal)",
            fontSize: 11,
            fontWeight: 600,
            padding: "3px 9px",
            borderRadius: 999,
            border: `1px solid ${room.availableNow === false ? "var(--coral)" : "var(--teal)"}`,
          }}
        >
          {room.availableNow === false ? "Unavailable" : "Available"}
        </span>
      </div>
    </div>
  );
}
